'use strict';
// Background home cats: sprite cats wander along the bottom of the viewport.
// Each cat picks weighted activities that follow its personality; sprites come from
// assets/home-cats/sprites.json (generated by build-assets/prepare-home-cats.py).
(() => {
const PERSONALITY={
 elu:{name:'Elu · 艾露',walk:58,run:280,sleep:[7,14],curious:true,
  weights:{wander:4,sit:2,groom:1.5,loaf:1.5,sleep:1,play:3.5,zoom:1.5,chase:2.5,snuggle:.5}},
 eevee:{name:'Eevee · 伊布',walk:38,run:190,sleep:[12,26],shy:true,
  weights:{wander:3,sit:3,groom:2,loaf:3,sleep:4,play:1,snuggle:1.5}},
};
const CALM=['sit','walk','loaf','groom'];
const WALK=['walk-contact','walk-passing','walk-opposite-contact','walk-opposite-passing'];
const hiddenKey='yuqi-home-cats-hidden';
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const rand=(a,b)=>a+Math.random()*(b-a);
const pick=weights=>{let r=Math.random()*Object.values(weights).reduce((a,b)=>a+b,0);for(const [k,w] of Object.entries(weights))if((r-=w)<0)return k;return Object.keys(weights)[0];};

let layer,ball,cats=[],raf=0,last=0,pointer={x:-1e4,y:0,t:-1e4};
const scale=()=>innerWidth<600?0.38:0.5;
const width=()=>document.documentElement.clientWidth;
const k=()=>scale()/0.5;
const other=cat=>cats.find(c=>c!==cat);

function makeCat(id,sprites){
 const el=document.createElement('div');el.className='home-cat';el.dataset.cat=id;el.title=PERSONALITY[id].name;
 const frames={};
 for(const [pose,s] of Object.entries(sprites)){
  const img=document.createElement('img');img.src='assets/home-cats/'+s.src;img.alt='';img.draggable=false;img.dataset.pose=pose;
  img.style.cssText=`width:${s.w}px;height:${s.h}px;left:${-s.ax}px`;img.hidden=true;el.append(img);frames[pose]=img;
 }
 const cat={id,el,frames,p:PERSONALITY[id],x:rand(80,width()-80),dir:Math.random()<.5?1:-1,state:'sit',t:0,dur:3,frame:null,plays:0,curiousAt:-1e4};
 el.addEventListener('click',()=>pet(cat));
 layer.append(el);return cat;
}
function show(cat,pose){
 if(cat.frame===pose)return;
 if(cat.frame)cat.frames[cat.frame].hidden=true;
 cat.frames[pose].hidden=false;cat.frame=pose;
}
function set(cat,state,opts={}){
 Object.assign(cat,{state,t:0,dur:opts.dur??1,target:opts.target,speed:opts.speed,after:opts.after||null});
 cat.el.dataset.state=state;
 if(opts.target!=null&&Math.abs(opts.target-cat.x)>1)cat.dir=Math.sign(opts.target-cat.x);
}
function bubble(cat,text,cls=''){
 const b=document.createElement('span');b.className='cat-bubble '+cls;b.textContent=text;
 b.style.left=cat.x+'px';b.style.bottom=(70*k()+16)+'px';
 layer.append(b);b.addEventListener('animationend',()=>b.remove());
}
function clampX(x){return Math.max(50,Math.min(width()-50,x));}

function decide(cat){
 const p=cat.p;
 switch(pick(p.weights)){
  case 'wander':return set(cat,'walk',{target:clampX(cat.x+rand(-1,1)*width()*.5)});
  case 'sit':return set(cat,'sit',{dur:rand(3,6)});
  case 'groom':return set(cat,'groom',{dur:rand(3,5),after:()=>set(cat,'sit',{dur:rand(1,2)})});
  case 'loaf':return set(cat,'loaf',{dur:rand(5,9)});
  case 'sleep':return set(cat,'sleep',{dur:rand(...p.sleep),after:()=>wake(cat)});
  case 'play':cat.plays=Math.floor(rand(2,5));return chaseBall(cat);
  case 'chase':return other(cat)?chase(cat,other(cat)):set(cat,'walk',{target:clampX(rand(.1,.9)*width())});
  case 'snuggle':{const mate=other(cat);return mate?.state==='sleep'?snuggle(cat,mate):set(cat,'loaf',{dur:rand(4,7)});}
  case 'zoom':{const edge=cat.x<width()/2?width()-60:60;return set(cat,'run',{target:edge,after:()=>set(cat,'run',{target:clampX(rand(.2,.8)*width()),after:()=>set(cat,'sit',{dur:rand(2,3)})})});}
 }
}
function wake(cat){set(cat,'stretch',{dur:1.6});}
function chaseBall(cat){
 const gap=ball.x-cat.x,side=gap>0?-1:1,spot=clampX(ball.x+side*34*scale()/0.5);
 if(cat.plays--<=0)return set(cat,'sit',{dur:rand(2,4)});
 const go=Math.abs(spot-cat.x)>160?'run':'walk';
 set(cat,go,{target:spot,after:()=>{
  cat.dir=Math.sign(ball.x-cat.x)||cat.dir;
  if(Math.random()<.35)set(cat,'pounce',{dur:.55,after:()=>{kick(cat,rand(180,300));chaseBall(cat);}});
  else set(cat,'play',{dur:.9,after:()=>{kick(cat,rand(90,220));chaseBall(cat);}});
 }});
}
function kick(cat,speed){ball.vx=cat.dir*speed;}
// Elu chases Eevee: Eevee flees at her own pace, Elu follows close behind and
// sometimes catches up for a short scuffle. A sleeping Eevee gets a nap buddy instead.
function chase(cat,prey){
 if(prey.state==='sleep')return snuggle(cat,prey);
 if(!CALM.includes(prey.state))return set(cat,'sit',{dur:rand(2,3)});
 const side=Math.sign(prey.x-cat.x)||1;
 set(cat,'run',{target:clampX(prey.x-side*90*k()),after:()=>{
  if(!CALM.includes(prey.state))return set(cat,'sit',{dur:rand(2,3)});
  const away=Math.sign(prey.x-cat.x)||1,goal=clampX(prey.x+away*rand(220,380)*k());
  if(Math.abs(goal-prey.x)<80*k())return scuffle(cat,prey);
  bubble(prey,'!');
  set(prey,'run',{target:goal,after:()=>{prey.dir=-away;set(prey,'sit',{dur:rand(3,5)});}});
  set(cat,'run',{target:clampX(goal-away*70*k()),speed:prey.p.run,after:()=>Math.random()<.5?scuffle(cat,prey):set(cat,'groom',{dur:rand(2,4),after:()=>set(cat,'sit',{dur:2})})});
 }});
}
function scuffle(a,b){
 a.dir=Math.sign(b.x-a.x)||1;b.dir=-a.dir;
 set(a,'scuffle',{dur:1.8,after:()=>set(a,'groom',{dur:rand(2,4),after:()=>set(a,'sit',{dur:2})})});
 set(b,'scuffle',{dur:1.8,after:()=>{bubble(b,'…');set(b,'sit',{dur:rand(3,5)});}});
}
function snuggle(cat,mate){
 const side=Math.sign(cat.x-mate.x)||1;
 set(cat,'walk',{target:clampX(mate.x+side*95*k()),after:()=>{cat.dir=-side;set(cat,'sleep',{dur:rand(...cat.p.sleep),after:()=>wake(cat)});}});
}
function pet(cat){
 if(cat.state==='sleep'){bubble(cat,'?');return wake(cat);}
 if(cat.p.shy&&Math.random()<.55){bubble(cat,'!');return set(cat,'run',{target:clampX(cat.x+(Math.random()<.5?-1:1)*rand(160,260)*k()),after:()=>set(cat,'loaf',{dur:rand(3,5)})});}
 bubble(cat,'♥','heart');
 set(cat,'pounce',{dur:.55,after:()=>set(cat,'sit',{dur:rand(2,3)})});
}
// When the pointer lingers near the bottom of the page, curious cats come over
// and shy cats back away.
function reactToPointer(cat,now){
 if(!CALM.includes(cat.state)||now-pointer.t>2500||pointer.y<innerHeight-240)return;
 const gap=pointer.x-cat.x;
 if(cat.p.curious&&now-cat.curiousAt>7000&&Math.abs(gap)>60&&Math.abs(gap)<420){
  cat.curiousAt=now;
  set(cat,'walk',{target:clampX(pointer.x-Math.sign(gap)*45),after:()=>{cat.dir=Math.sign(pointer.x-cat.x)||cat.dir;set(cat,'sit',{dur:rand(3,5)});}});
 }else if(cat.p.shy&&now-cat.curiousAt>4000&&Math.abs(gap)<110*k()){
  cat.curiousAt=now;
  set(cat,'walk',{target:clampX(cat.x-(Math.sign(gap)||1)*rand(160,240)*k()),after:()=>set(cat,'loaf',{dur:rand(3,6)})});
 }
}

function step(cat,dt,now){
 cat.t+=dt;
 const moving=cat.state==='walk'||cat.state==='run';
 if(moving){
  const speed=(cat.speed??(cat.state==='run'?cat.p.run:cat.p.walk))*k(),left=cat.target-cat.x;
  if(Math.abs(left)<=speed*dt){cat.x=cat.target;cat.after?cat.after():decide(cat);}
  else{cat.dir=Math.sign(left);cat.x+=cat.dir*speed*dt;}
 }else if(cat.state==='pounce'){cat.x=clampX(cat.x+cat.dir*150*dt*k());if(cat.t>=cat.dur)cat.after?cat.after():decide(cat);}
 else if(cat.t>=cat.dur){cat.after?cat.after():decide(cat);}
 reactToPointer(cat,now);
 const every=n=>Math.floor(cat.t/n)!==Math.floor((cat.t-dt)/n);
 if(cat.state==='sleep'&&every(1.6))bubble(cat,'z','zzz');
 if(cat.state==='scuffle'&&cat.dir>0&&every(.45))bubble({x:cat.x+30*k()},'✦','puff');
 const pose={walk:WALK[Math.floor(cat.t*7)%4],run:['run','pounce'][Math.floor(cat.t*8)%2],play:['play','walk-passing'][Math.floor(cat.t*3.3)%2],scuffle:['pounce','play'][Math.floor(cat.t*4)%2]}[cat.state]||cat.state;
 show(cat,pose);
 cat.el.style.transform=`translateX(${cat.x}px) scale(${cat.dir*scale()},${scale()})`;
}
function stepBall(dt){
 ball.x+=ball.vx*dt;ball.vx*=Math.exp(-1.5*dt);
 if(ball.x<20||ball.x>width()-20){ball.x=Math.max(20,Math.min(width()-20,ball.x));ball.vx*=-.6;}
 ball.spin+=ball.vx*dt*4;
 ball.el.style.transform=`translateX(${ball.x}px) rotate(${ball.spin}deg)`;
}
function loop(now){
 const dt=Math.min(.1,(now-last)/1000);last=now;
 stepBall(dt);cats.forEach(c=>step(c,dt,now));
 raf=requestAnimationFrame(loop);
}
function start(){
 cancelAnimationFrame(raf);
 if(reduced.matches){cats.forEach((c,i)=>{c.x=clampX(width()-90-i*110*k());c.dir=-1;set(c,'loaf',{dur:Infinity});step(c,0,0);});stepBall(0);return;}
 last=performance.now();raf=requestAnimationFrame(loop);
}
function setHidden(hidden,button){
 layer.hidden=hidden;document.body.classList.toggle('cat-floor',!hidden);button.textContent=hidden?'Show my cats':'Hide my cats';button.setAttribute('aria-pressed',String(!hidden));
 try{localStorage.setItem(hiddenKey,String(hidden));}catch{}
 if(hidden)cancelAnimationFrame(raf);else start();
}

async function init(){
 let manifest;
 try{manifest=await (await fetch('assets/home-cats/sprites.json')).json();}catch{return;}
 layer=document.createElement('div');layer.className='home-cats';layer.setAttribute('aria-hidden','true');
 ball={el:document.createElement('span'),x:rand(.3,.7)*width(),vx:0,spin:0};ball.el.className='cat-toy';layer.append(ball.el);
 document.body.append(layer);
 cats=Object.keys(PERSONALITY).filter(id=>manifest[id]).map(id=>makeCat(id,manifest[id]));
 cats.forEach((c,i)=>{c.x=clampX((i+.5)/cats.length*width()+rand(-80,80));});
 cats.forEach(c=>Math.random()<.4?set(c,'sleep',{dur:rand(...c.p.sleep),after:()=>wake(c)}):set(c,'sit',{dur:rand(2,4)}));
 addEventListener('pointermove',e=>{pointer={x:e.clientX,y:e.clientY,t:performance.now()};},{passive:true});
 addEventListener('resize',()=>{cats.forEach(c=>{c.x=clampX(c.x);});ball.x=Math.min(ball.x,width()-20);});
 reduced.addEventListener?.('change',start);
 const button=document.querySelector('[data-cats-toggle]');
 let hidden=false;try{hidden=localStorage.getItem(hiddenKey)==='true';}catch{}
 if(button){button.hidden=false;button.addEventListener('click',()=>setHidden(!layer.hidden,button));setHidden(hidden,button);}
 else{document.body.classList.add('cat-floor');start();}
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
